import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class GroupTotals {

    record Booking(String city, int total) {
    }

    public static void main(String[] args) {
        List<Booking> bookings = List.of(
                new Booking("Budapest", 240),
                new Booking("Praha", 120),
                new Booking("Budapest", 80));

        // Data shape: Map<String, Integer>, city to revenue, keys sorted.
        Map<String, Integer> revenue = bookings.stream()
                .collect(Collectors.groupingBy(
                        Booking::city,
                        TreeMap::new,                        // sorted keys
                        Collectors.summingInt(Booking::total)));
        System.out.println(revenue); // {Budapest=320, Praha=120}

        // The two argument form drops the map factory: HashMap, order not promised.
        Map<String, Long> counts = bookings.stream()
                .collect(Collectors.groupingBy(Booking::city, Collectors.counting()));
        System.out.println(counts);
    }
}

// File: SplitByBreakfast.java
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class SplitByBreakfast {

    record Booking(boolean breakfast, int total) {
    }

    public static void main(String[] args) {
        List<Booking> bookings = List.of(
                new Booking(true, 276),
                new Booking(false, 380),
                new Booking(false, 60));

        // Data shape: Map<Boolean, Long>. Both keys exist even when a side is empty.
        Map<Boolean, Long> counts = bookings.stream()
                .collect(Collectors.partitioningBy(Booking::breakfast, Collectors.counting()));
        System.out.println(counts.get(true) + " with, " + counts.get(false) + " without");

        // averagingInt gives 0.0 for an empty side. No Optional, no missing key.
        Map<Boolean, Double> averages = bookings.stream()
                .collect(Collectors.partitioningBy(
                        Booking::breakfast,
                        Collectors.averagingInt(Booking::total)));
        System.out.println(averages); // {false=220.0, true=276.0}
    }
}

// File: MergeMap.java
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class MergeMap {

    record Booking(String hotel, int total) {
    }

    public static void main(String[] args) {
        List<Booking> bookings = List.of(
                new Booking("Danube View", 240),
                new Booking("City Inn", 120),
                new Booking("Danube View", 80));

        // Data shape: Map<String, Integer>, hotel to revenue, sorted keys.
        // The third argument is the merge function. Without it the second
        // Danube View row throws IllegalStateException: Duplicate key.
        Map<String, Integer> revenue = bookings.stream()
                .collect(Collectors.toMap(
                        Booking::hotel,     // key
                        Booking::total,     // value
                        Integer::sum,       // merge two rows with the same key
                        TreeMap::new));     // optional: map implementation
        System.out.println(revenue); // {City Inn=120, Danube View=320}

        // The merge function can keep the later row instead of adding the two.
        Map<String, Integer> last = bookings.stream()
                .collect(Collectors.toMap(Booking::hotel, Booking::total, (left, right) -> right));
        System.out.println(last);
    }
}

