import java.util.Comparator;
import java.util.List;

public class TopThree {

    record Booking(String hotel, int total) {
    }

    public static void main(String[] args) {
        List<Booking> bookings = List.of(
                new Booking("Danube View", 240),
                new Booking("City Inn", 120),
                new Booking("Danube View", 400),
                new Booking("Alpen Hof", 380),
                new Booking("City Inn", 60));

        // Data shape: List<Booking> -> List<String>, order and length decided here.
        // distinct then limit: three different hotels.
        List<String> hotels = bookings.stream()
                .map(Booking::hotel)
                .distinct()
                .sorted()
                .limit(2)
                .toList();
        System.out.println(hotels); // [Alpen Hof, City Inn]

        // limit then distinct can return fewer rows than asked for, because
        // the duplicates were already inside the cut. Order matters.
        long fewer = bookings.stream()
                .map(Booking::hotel)
                .limit(3)
                .distinct()
                .count();
        System.out.println(fewer); // 2, not 3: the third hotel was a repeat

        // Top 3 by value: sort descending first, then cut.
        List<String> top = bookings.stream()
                .sorted(Comparator.comparingInt(Booking::total).reversed())
                .limit(3)
                .map(b -> b.hotel() + "=" + b.total())
                .toList();
        System.out.println(top);
    }
}

// File: OptionalChain.java
import java.util.List;
import java.util.Optional;

public class OptionalChain {

    record Booking(String city, int nights, String phone) {
    }

    public static void main(String[] args) {
        List<Booking> bookings = List.of(
                new Booking("Budapest", 3, "+36 1 555 0100"),
                new Booking("Praha", 1, null));

        // Data shape: List<Booking> -> Optional<String>.
        // findFirst returns Optional. map keeps the empty case alive, so the
        // rest of the chain needs no null check.
        String city = bookings.stream()
                .filter(b -> b.nights() > 2)
                .map(Booking::city)
                .findFirst()
                .map(String::toUpperCase)
                .orElse("no long stay");
        System.out.println(city); // BUDAPEST

        // A nullable column becomes Optional with ofNullable, then disappears
        // from the stream with Optional::stream.
        Optional<String> phone = bookings.stream()
                .filter(b -> b.city().equals("Praha"))
                .findFirst()
                .flatMap(b -> Optional.ofNullable(b.phone()));
        System.out.println(phone.orElse("no phone on file"));
    }
}

